function subCode(cat,x){var a=SUBS[cat]||[];for(var i=0;i<a.length;i++)if(a[i][0]===x)return x;return""}
function setFromUrl(){
  var p=new URLSearchParams(location.search),rest=[];F=blank();
  (p.get("q")||"").toLowerCase().split("-").forEach(function(x){
    if(!x)return;
    if(x==="set"||(CAT[x]&&x!=="gloves"))F.cat=x;
    else if(COLBY[x])F.col[COLBY[x]]=true;
    else if(x==="all")F.stock=false;
    else rest.push(x)});
  rest.forEach(function(x){
    if(F.cat==="gloves"){
      if(KC[x]){if(!any(F.kind))F.kind[KC[x]]=true}
      else if(x==="velcro"||x==="lace")F.clo[x]=true;
      else if(/^\d+$/.test(x))F.oz[+x]=true;
      else if(/^(s|m|l|xl)$/.test(x))F.let[x.toUpperCase()]=true}
    else if(F.cat!=="set"){if(subCode(F.cat,x))F.sub[x]=true;else F.sz[x]=true}});
  MODEL="";var m=p.get("m");
  if(m){var all={};V.forEach(function(v){all[slug(v.model)]=v.model});Object.keys(D.meta).forEach(function(k){all[slug(k)]=k});if(all[m.toLowerCase()])MODEL=all[m.toLowerCase()]}}
function toQuery(){
  var parts=[],k=keys(F.kind)[0];
  if(F.cat!=="gloves")parts.push(F.cat);
  if(F.cat==="gloves"){
    if(k)for(var c in KC)if(KC[c]===k)parts.push(c);
    keys(F.clo).forEach(function(c){parts.push(c)});
    keys(F.oz).sort(function(a,b){return a-b}).forEach(function(o){parts.push(o)});
    keys(F.let).forEach(function(l){parts.push(l.toLowerCase())})}
  else if(F.cat!=="set"){keys(F.sub).forEach(function(s){parts.push(s)});keys(F.sz).forEach(function(s){parts.push(s)})}
  COL.forEach(function(c){if(F.col[c[0]])parts.push(c[1])});
  if(!F.stock)parts.push("all");
  var q=[];if(parts.length)q.push("q="+parts.join("-"));
  if(MODEL)q.push("m="+slug(MODEL));
  return q.length?"?"+q.join("&"):""}
